import http.server, socketserver, threading, subprocess

requests = []

class TestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self): self.record()
    def do_POST(self): self.record()
    def do_DELETE(self): self.record()
    def record(self):
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)
        requests.append({
            'command': self.command,
            'path': self.path,
            'headers': dict(self.headers),
            'body': body
        })
        self.send_response(200)
        self.end_headers()

server = socketserver.TCPServer(('127.0.0.1', 0), TestHandler)
port = server.server_address[1]
threading.Thread(target=server.serve_forever, daemon=True).start()

def test(args):
    requests.clear()
    res = subprocess.run(['./executable'] + args, capture_output=True, text=True)
    if requests:
        print(f'Args: {args}')
        print(f'  Method: {requests[0][\"command\"]}, Path: {requests[0][\"path\"]}')
        print(f'  Headers: {requests[0][\"headers\"]}')
        print(f'  Body: {repr(requests[0][\"body\"])}')
    else:
        print(f'Args: {args} -> No request. Error: {res.stderr.strip()}')

test(['GET', f'127.0.0.1:{port}', 'a=1', 'b=2'])
test(['DELETE', f'127.0.0.1:{port}', 'a=1'])
test(['127.0.0.1:{port}?x=0', 'a=1'])
test(['GET', f'127.0.0.1:{port}?x=0', 'a=1'])
""}

