import pty, os, sys, http.server, socketserver, threading

class TestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/404':
            self.send_error(404, 'Not Found')
        elif self.path == '/500':
            self.send_error(500, 'Internal Error')
        elif self.path == '/302':
            self.send_response(302)
            self.send_header('Location', '/other')
            self.end_headers()

server = socketserver.TCPServer(('127.0.0.1', 0), TestHandler)
port = server.server_address[1]
threading.Thread(target=server.serve_forever, daemon=True).start()

def run_in_pty(args):
    master, slave = pty.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.close(slave)
        os.execvp(args[0], args)
    else:
        os.close(slave)
        output = b''
        while True:
            try:
                data = os.read(master, 1024)
                if not data: break
                output += data
            except OSError:
                break
        os.close(master)
        os.waitpid(pid, 0)
        return output

for path in ['/404', '/500', '/302']:
    out = run_in_pty(['./executable', '-print=h', f'127.0.0.1:{port}{path}'])
    print(f'Path: {path} -> Output:\n{repr(out.decode(\"utf-8\", errors=\"replace\"))}\n')
""}

