{"command":"cat << 'EOF' > bat.go
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

const usageText = `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat

`

var (
	authVal     string
	benchVal    bool
	benchN      int
	benchC      int
	bodyVal     string
	formVal     bool
	jsonVal     bool
	prettyVal   bool
	insecureVal bool
	proxyVal    string
	printVal    string
	versionVal  bool
)

func isatty(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)

	flag.CommandLine.Usage = func() {
		fmt.Print(usageText)
	}

	flag.StringVar(&authVal, "a", "", "")
	flag.StringVar(&authVal, "auth", "", "")
	flag.BoolVar(&benchVal, "b", false, "")
	flag.BoolVar(&benchVal, "bench", false, "")
	flag.IntVar(&benchN, "b.N", 1000, "")
	flag.IntVar(&benchC, "b.C", 100, "")
	flag.StringVar(&bodyVal, "body", "", "")
	flag.BoolVar(&formVal, "f", false, "")
	flag.BoolVar(&formVal, "form", false, "")
	flag.BoolVar(&jsonVal, "json", true, "")
	flag.BoolVar(&prettyVal, "p", true, "")
	flag.BoolVar(&prettyVal, "pretty", true, "")
	flag.BoolVar(&insecureVal, "i", false, "")
	flag.BoolVar(&insecureVal, "insecure", false, "")
	flag.StringVar(&proxyVal, "proxy", "", "")
	flag.StringVar(&printVal, "print", "A", "")
	flag.BoolVar(&versionVal, "v", false, "")
	flag.BoolVar(&versionVal, "version", false, "")

	flag.Parse()

	if versionVal {
		fmt.Println("Version: 0.1.0")
		os.Exit(2)
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.CommandLine.Usage()
		os.Exit(2)
	}

	validMethods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true,
		"HEAD": true, "OPTIONS": true, "PATCH": true,
	}

	var method string
	var rawURL string
	var items []string

	firstUpper := strings.ToUpper(args[0])
	if validMethods[firstUpper] {
		method = firstUpper
		if len(args) < 2 {
			flag.CommandLine.Usage()
			os.Exit(2)
		}
		rawURL = args[1]
		items = args[2:]
	} else {
		rawURL = args[0]
		items = args[1:]
	}

	headers := make(map[string]string)
	queryParams := make(map[string]string)
	bodyParams := make(map[string]string)

	for _, item := range items {
		if idx := strings.Index(item, "=@"); idx != -1 {
			k := item[:idx]
			filepath := item[idx+2:]
			data, err := os.ReadFile(filepath)
			if err != nil {
				log.Fatalf("Read File%s%s", filepath, err)
			}
			bodyParams[k] = string(data)
		} else if idx := strings.Index(item, ":"); idx != -1 {
			k := item[:idx]
			v := strings.TrimSpace(item[idx+1:])
			headers[k] = v
		} else if strings.Contains(item, "==") {
			idx := strings.Index(item, "=")
			k := item[:idx]
			v := item[idx+1:]
			if method != "" && method != "GET" && method != "HEAD" {
				bodyParams[k] = v
			} else {
				queryParams[k] = v
			}
		} else if idx := strings.Index(item, "="); idx != -1 {
			k := item[:idx]
			v := item[idx+1:]
			if method == "GET" || method == "HEAD" {
				queryParams[k] = v
			} else {
				bodyParams[k] = v
			}
		}
	}

	if method == "" {
		if len(bodyParams) > 0 {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	if benchVal {
		runBench(method, rawURL, headers, queryParams, bodyParams)
	} else {
		runHTTP(method, rawURL, headers, queryParams, bodyParams)
	}
}
EOF"}

