{"command":"cat << 'EOF' > http.go
package main

import (
	"bytes"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strings"
)

func parseURL(urlStr string) string {
	if strings.HasPrefix(urlStr, ":") {
		urlStr = "localhost" + urlStr
	}
	if !strings.HasPrefix(urlStr, "http://") && !strings.HasPrefix(urlStr, "https://") {
		urlStr = "http://" + urlStr
	}
	return urlStr
}

func runHTTP(method, rawURL string, headers, queryParams, bodyParams map[string]string) {
	fullURL := parseURL(rawURL)

	u, err := url.Parse(fullURL)
	if err != nil {
		log.Fatalf("can't get the url %s", err)
	}

	if len(queryParams) > 0 {
		q := u.Query()
		for k, v := range queryParams {
			q.Add(k, v)
		}
		u.RawQuery = q.Encode()
	}

	var reqBody []byte
	var contentType string

	if bodyVal != "" {
		reqBody = []byte(bodyVal)
	} else if formVal && len(bodyParams) > 0 {
		contentType = "application/x-www-form-urlencoded"
		formValues := url.Values{}
		for k, v := range bodyParams {
			formValues.Add(k, v)
		}
		reqBody = []byte(formValues.Encode())
	} else if jsonVal && len(bodyParams) > 0 {
		contentType = "application/json"
		data, err := json.Marshal(bodyParams)
		if err != nil {
			log.Fatalf("json marshal error: %s", err)
		}
		data = append(data, '\n')
		reqBody = data
	}

	req, err := http.NewRequest(method, u.String(), bytes.NewReader(reqBody))
	if err != nil {
		log.Fatalf("can't get the url %s", err)
	}

	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}

	req.Header.Set("User-Agent", "bat/0.1.0")
	if jsonVal {
		req.Header.Set("Accept", "application/json")
	} else {
		req.Header.Set("Accept", "*/*")
	}
	req.Header.Set("Accept-Encoding", "gzip, deflate")

	if authVal != "" {
		encoded := base64.StdEncoding.EncodeToString([]byte(authVal))
		req.Header.Set("Authorization", "Basic "+encoded)
	}

	for k, v := range headers {
		req.Header.Set(k, v)
	}

	tr := &http.Transport{}
	if insecureVal {
		tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if proxyVal != "" {
		proxyURL, err := url.Parse(proxyVal)
		if err != nil {
			log.Fatalf("can't get the url %s", err)
		}
		tr.Proxy = http.ProxyURL(proxyURL)
	}

	client := &http.Client{
		Transport: tr,
	}

	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %s", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("can't read response body: %s", err)
	}

	printOutput(req, reqBody, resp, respBody)
}

func printOutput(req *http.Request, reqBody []byte, resp *http.Response, respBody []byte) {
	tty := isatty(os.Stdout.Fd())

	if !tty {
		bodyStr := string(respBody)
		if prettyVal && isJSON(respBody) {
			var buf bytes.Buffer
			if err := json.Indent(&buf, respBody, "", "  "); err == nil {
				bodyStr = buf.String()
			}
		}
		fmt.Printf("\n%s", bodyStr)
		return
	}

	p := printVal
	if p == "A" {
		p = "HBhb"
	}

	if strings.Contains(p, "H") {
		path := req.URL.RequestURI()
		if path == "" {
			path = "/"
		}
		fmt.Printf("\x1b[95m%s\x1b[0m \x1b[96m%s\x1b[0m \x1b[95m%s\r\x1b[0m\r\n", req.Method, path, req.Proto)

		// Print request headers in standard order
		printReqHeader(req, "Host", req.URL.Host)
		if req.Header.Get("Accept") != "" {
			printReqHeader(req, "Accept", req.Header.Get("Accept"))
		}
		if req.Header.Get("Accept-Encoding") != "" {
			printReqHeader(req, "Accept-Encoding", req.Header.Get("Accept-Encoding"))
		}
		if req.Header.Get("Content-Type") != "" {
			printReqHeader(req, "Content-Type", req.Header.Get("Content-Type"))
		}
		if req.Header.Get("User-Agent") != "" {
			printReqHeader(req, "User-Agent", req.Header.Get("User-Agent"))
		}
		if req.Header.Get("Authorization") != "" {
			printReqHeader(req, "Authorization", req.Header.Get("Authorization"))
		}

		for k, v := range req.Header {
			if k == "Host" || k == "Accept" || k == "Accept-Encoding" || k == "Content-Type" || k == "User-Agent" || k == "Authorization" {
				continue
			}
			printReqHeader(req, k, strings.Join(v, ", "))
		}
		fmt.Print("\r\n")
	}

	if strings.Contains(p, "B") && len(reqBody) > 0 {
		fmt.Printf("\r\r\n%s\r\n\r\n\r\n", string(reqBody))
	}

	if strings.Contains(p, "h") {
		fmt.Printf("\x1b[95m%s\x1b[0m \x1b[92m%s\x1b[0m\r\n", resp.Proto, resp.Status)
		for k, v := range resp.Header {
			fmt.Printf("\x1b[90m%s\x1b[0m: \x1b[96m%s\x1b[0m\r\n", k, strings.Join(v, ", "))
		}
		fmt.Print("\r\n")
	}

	if strings.Contains(p, "b") && len(respBody) > 0 {
		if isJSON(respBody) {
			bodyStr := string(respBody)
			if prettyVal {
				var buf bytes.Buffer
				if err := json.Indent(&buf, respBody, "", "  "); err == nil {
					bodyStr = buf.String()
				}
			}
			colored := colorizeJSON(bodyStr)
			fmt.Printf("\r\n%s\r\n", colored)
		} else {
			bodyStr := string(respBody)
			fmt.Printf("\r\n\x1b[92m%s\x1b[0m\r\n", bodyStr)
		}
	}
}

func printReqHeader(req *http.Request, key, val string) {
	if val != "" {
		fmt.Printf("\x1b[90m%s\x1b[0m:\x1b[96m %s\r\x1b[0m\r\n", key, val)
	}
}

func isJSON(b []byte) bool {
	var js json.RawMessage
	return json.Unmarshal(b, &js) == nil
}

func colorizeJSON(jsonStr string) string {
	lines := strings.Split(jsonStr, "\n")
	var colored []string

	reKeyStr := regexp.MustCompile(`^(\s*)"([^"]+)":\s*"([^"]*)"(,?)$`)
	reKeyNum := regexp.MustCompile(`^(\s*)"([^"]+)":\s*(true|false|null|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(,?)$`)
	reKeyObj := regexp.MustCompile(`^(\s*)"([^"]+)":\s*([{\\[])(.*)$`)
	reArrStr := regexp.MustCompile(`^(\s*)"([^"]*)"(,?)$`)
	reArrNum := regexp.MustCompile(`^(\s*)(true|false|null|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(,?)$`)

	for _, line := range lines {
		line = strings.TrimRight(line, "\r")
		if m := reKeyStr.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf(`%s"\x1b[95m%s\x1b[0m": "\x1b[96m%s\x1b[0m"%s`, m[1], m[2], m[3], m[4])
		} else if m := reKeyNum.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf(`%s"\x1b[95m%s\x1b[0m": \x1b[96m%s\x1b[0m%s`, m[1], m[2], m[3], m[4])
		} else if m := reKeyObj.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf(`%s"\x1b[95m%s\x1b[0m": %s%s`, m[1], m[2], m[3], m[4])
		} else if m := reArrStr.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf(`%s"\x1b[95m%s\x1b[0m"%s`, m[1], m[2], m[3])
		} else if m := reArrNum.FindStringSubmatch(line); m != nil {
			c := "95"
			if m[2][0] >= '0' && m[2][0] <= '9' || m[2][0] == '-' {
				c = "96"
			}
			line = fmt.Sprintf(`%s\x1b[%sm%s\x1b[0m%s`, m[1], c, m[2], m[3])
		}
		colored = append(colored, line)
	}

	return strings.Join(colored, "\r\n")
}
EOF"}

