	slowest := 0.0
	fastest := math.MaxFloat64

	for _, r := range results {
		if r.err != nil {
			errorDist[r.err.Error()]++
		} else {
			statusCodes[r.status]++
			s := r.duration.Seconds()
			durations = append(durations, s)
			sumDuration += s
			if s > slowest {
				slowest = s
			}
			if s < fastest {
				fastest = s
			}
		}
	}

	totalSec := totalTime.Seconds()
	avgSec := 0.0
	if len(durations) > 0 {
		avgSec = sumDuration / float64(len(durations))
	} else {
		fastest = 0.0
	}

	reqPerSec := 0.0
	if totalSec > 0 {
		reqPerSec = float64(len(results)) / totalSec
	}

	fmt.Println("Summary:")
	fmt.Printf("  Total:\t%.4f secs.\n", totalSec)
	fmt.Printf("  Slowest:\t%.4f secs.\n", slowest)
	fmt.Printf("  Fastest:\t%.4f secs.\n", fastest)
	fmt.Printf("  Average:\t%.4f secs.\n", avgSec)
	fmt.Printf("  Requests/sec:\t%.4f\n\n", reqPerSec)

	if len(statusCodes) > 0 {
		fmt.Println("Status code distribution:")
		var codes []int
		for code := range statusCodes {
			codes = append(codes, code)
		}
		sort.Ints(codes)
		for _, code := range codes {
			fmt.Printf("  [%d]\t%d responses\n", code, statusCodes[code])
		}
		fmt.Println()
	}

	if len(durations) > 0 {
		sort.Float64s(durations)

		fmt.Println("Response time histogram:")
		numBuckets := 11
		minD := fastest
		maxD := slowest
		step := (maxD - minD) / float64(numBuckets)
		if step == 0 {
			step = 0.001
		}

		bucketCounts := make([]int, numBuckets)
		maxCount := 0
		for _, d := range durations {
			idx := int((d - minD) / step)
			if idx >= numBuckets {
				idx = numBuckets - 1
			}
			if idx < 0 {
				idx = 0
			}
			bucketCounts[idx]++
			if bucketCounts[idx] > maxCount {
				maxCount = bucketCounts[idx]
			}
		}

		for i := 0; i < numBuckets; i++ {
			bc := bucketCounts[i]
			barLen := 0
			if maxCount > 0 && bc > 0 {
				barLen = (bc * 40) / maxCount
			}
			bars := ""
			for b := 0; b < barLen; b++ {
				bars += "∎"
			}
			bucketMax := minD + float64(i+1)*step
			fmt.Printf("  %.3f [%d]\t|%s\n", bucketMax, bc, bars)
		}
		fmt.Println()

		fmt.Println("Latency distribution:")
		pcts := []int{10, 25, 50, 75, 90, 95, 99}
		for _, p := range pcts {
			idx := (len(durations) * p) / 100
			if idx >= len(durations) {
				idx = len(durations) - 1
			}
			if idx < 0 {
				idx = 0
			}
			fmt.Printf("  %d%% in %.4f secs.\n", p, durations[idx])
		}
		fmt.Println()
	}

	if len(errorDist) > 0 {
		fmt.Println("Error distribution:")
		for errStr, count := range errorDist {
			fmt.Printf("  [%d]\t%s\n", count, errStr)
		}
		fmt.Println()
	}
}
EOF"}

