	var colored []string

	reKeyStr := regexp.MustCompile(`^(\s*)"([^"]+)":\s*"([^"]*)"(,?)$`)
	reKeyNum := regexp.MustCompile(`^(\s*)"([^"]+)":\s*(true|false|null|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(,?)$`)
	reKeyObj := regexp.MustCompile(`^(\s*)"([^"]+)":\s*([{\\[])(.*)$`)
	reArrStr := regexp.MustCompile(`^(\s*)"([^"]*)"(,?)$`)
	reArrNum := regexp.MustCompile(`^(\s*)(true|false|null|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(,?)$`)

	for _, line := range lines {
		line = strings.TrimRight(line, "\r")
		if m := reKeyStr.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf("%s\"\x1b[95m%s\x1b[0m\": \"\x1b[96m%s\x1b[0m\"%s", m[1], m[2], m[3], m[4])
		} else if m := reKeyNum.FindStringSubmatch(line); m != nil {
