			}
			line = fmt.Sprintf("%s\"\x1b[95m%s\x1b[0m\": \x1b[96m%s%s", m[1], m[2], m[3], valSuffix)
		} else if m := reKeyObj.FindStringSubmatch(line); m != nil {
			line = fmt.Sprintf("%s\"\x1b[95m%s\x1b[0m\": %s%s", m[1], m[2], m[3], m[4])
		} else if m := reArrStr.FindStringSubmatch(line); m != nil {
